#include <stdio.h>

int main(void) {
    int N, X, Y, Z;
    scanf("%d %d %d %d", &N, &X, &Y, &Z);

    int costs[3] = {X, Y, Z};

    for (int i = 0; i < 2; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (costs[i] > costs[j]) {
                int temp = costs[i];
                costs[i] = costs[j];
                costs[j] = temp;
            }
        }
    }

    int count = 0;
    for (int i = 0; i < 3; i++) {
        if (N >= costs[i]) {
            N -= costs[i];
            count++;
        } else {
            break;
        }
    }

    printf("%d\n", count);
    return 0;
}
